question.solution:
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class BST:
    def __init__(self):
        self.root = None

    def insert(self, val):
        if self.root is None:
            self.root = TreeNode(val)
            return True
        node = self.root
        while True:
            if val == node.val:
                return False
            if val < node.val:
                if node.left is None:
                    node.left = TreeNode(val)
                    return True
                node = node.left
            else:
                if node.right is None:
                    node.right = TreeNode(val)
                    return True
                node = node.right

    def search(self, val):
        node = self.root
        while node is not None:
            if val == node.val:
                return True
            if val < node.val:
                node = node.left
            else:
                node = node.right
        return False

tree = BST()
for value in [50, 30, 70, 20, 40, 60, 80]:
    tree.insert(value)

def inorder(node, out):
    if node is None:
        return out
    inorder(node.left, out)
    out.append(node.val)
    inorder(node.right, out)
    return out

print(inorder(tree.root, []))
print(tree.search(40), tree.search(99))
print(tree.insert(50))

