def _inorder(node):
    if node is None:
        return []
    return _inorder(node.left) + [node.val] + _inorder(node.right)

def _count(node):
    if node is None:
        return 0
    return 1 + _count(node.left) + _count(node.right)

def _is_bst(node, low=None, high=None):
    if node is None:
        return True
    if low is not None and node.val <= low:
        return False
    if high is not None and node.val >= high:
        return False
    return _is_bst(node.left, low, node.val) and _is_bst(node.right, node.val, high)

